mapper.select:
SELECT id, leaf_bytes FROM attestations
 WHERE batch_id IS NULL AND kind <> 'inscription' AND org_id = #{orgId}
 ORDER BY created_at ASC, rowseq ASC LIMIT #{limit} FOR UPDATE

SELECT id FROM batches
 WHERE status = 'sealed' AND id <> #{except}
 ORDER BY sealed_at ASC, id ASC LIMIT 1

mapper.update:
UPDATE anchor_txs SET status = 'confirmed', block_height = #{blockHeight}, block_hash = #{blockHash},
       confirmations = #{confirmations}, confirmed_at = #{confirmedAt}
 WHERE txid = #{txid} AND status != 'confirmed'

UPDATE attestations SET status = 'confirmed', block_height = #{blockHeight}, block_hash = #{blockHash},
       confirmations = #{confirmations}
 WHERE id = #{id} AND status != 'confirmed'
